def is_multiply_prime(a: int) -> bool:
    """
    Return True if `a` is the product of exactly three prime numbers
    (not necessarily distinct), otherwise False. Assumes 0 < a < 100.
    """
    if a < 8:  # 2*2*2 is the smallest product of three primes
        return False

    # Simple prime checker for small numbers
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n in (2, 3):
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # List of primes up to a (since a < 100 this is tiny)
    primes = [p for p in range(2, a + 1) if is_prime(p)]

    # Try all combinations of three primes (order matters not)
    for i, p1 in enumerate(primes):
        for j, p2 in enumerate(primes):
            for k, p3 in enumerate(primes):
                if p1 * p2 * p3 == a:
                    return True
    return False
